{
  "title_fr": "Guide rapide pour localiser la documentation publique en franais",
  "summary_fr": "Cette note explique comment adapter la documentation publique d'un dpt tout en conservant les chanes oprationnelles exactes.",
  "lines": [
    {
      "line_no": 1,
      "fr": "`mistral-subagent` est utilis uniquement comme assistant subordonn."
    },
    {
      "line_no": 2,
      "fr": "Codex conserve le contrle des fichiers locaux, des secrets, de Git, des tests et de la vrification finale."
    },
    {
      "line_no": 3,
      "fr": "Gardez `MISTRAL_API_KEY` priv et chargez-le localement."
    },
    {
      "line_no": 4,
      "fr": "Utilisez `mistral-small-latest` pour une premire traduction conomique."
    },
    {
      "line_no": 5,
      "fr": "Utilisez `mistral-medium-3.5` lorsque la note en franais doit rester prcise et publique."
    },
    {
      "line_no": 6,
      "fr": "Utilisez `mistral-large-latest` lorsque la qualit de formulation prime sur le cot."
    },
    {
      "line_no": 7,
      "fr": "Excutez `node mistral-subagent/scripts/mistral-subagent.mjs check` avant `node mistral-subagent/scripts/mistral-subagent.mjs run`."
    }
  ],
  "preserved_literals": [
    "mistral-subagent",
    "MISTRAL_API_KEY",
    "mistral-small-latest",
    "mistral-medium-3.5",
    "mistral-large-latest",
    "node mistral-subagent/scripts/mistral-subagent.mjs check",
    "node mistral-subagent/scripts/mistral-subagent.mjs run"
  ]
}
